        uint256 taxFeeAfter = token._taxFee();
        console.log("_taxFee after:", taxFeeAfter);
        if (taxFeeAfter != 10) {
            failureMessage = string(abi.encodePacked(failureMessage, "Tax fee not updated; "));
            changesSuccessful = false;
